  justify-content: space-between;
  gap: 16px;
  color: var(--text-primary);
  font-size: 1.1rem;
  font-weight: 600;
  transition: all 0.2s ease;
}

.faq-button:hover {
  background-color: var(--bg-tertiary);
  color: var(--accent-hover);
